<?php\n/**\n * Script principal para executar o scraping completo do site CCCRJ\n */\n\n// Incluir os arquivos e definir as classes\ninclude_once 'scraper.php';\ninclude_once 'image_finder.php';\n\necho \"Iniciando processo de scraping do site CCCRJ...\\n\";\n\n// Executar o scraper principal\necho \"\\nEtapa 1: Executando scraper principal...\\n\";\n$start = microtime(true);\n\n$scraper = new CCCRJScraper();\n$scraper->run();\n\n$end = microtime(true);\necho \"Scraper principal conclu\\u00eddo em \" . ($end - $start) . \" segundos\\n\";\n\n// Executar o finder de imagens\necho \"\\nEtapa 2: Procurando e baixando imagens adicionais...\\n\";\n$start = microtime(true);\n\n$imageFinder = new ImageFinder();\n$imageFinder->findAndDownloadImages();\n\n$end = microtime(true);\necho \"Download de imagens conclu\\u00eddo em \" . ($end - $start) . \" segundos\\n\";\n\necho \"\\nProcesso de scraping conclu\\u00eddo com sucesso!\\n\";\necho \"Conte\\u00fados salvos na pasta: cccrj_content\\n\";\n\n?>